import{_ as t,o as r,c as a,a3 as o}from"./chunks/framework.By61hD98.js";const h=JSON.parse('{"title":"Bybit SDK production usage","description":"Handle Bybit retries, uncertain order outcomes, stream recovery and shutdown.","frontmatter":{"title":"Bybit SDK production usage","description":"Handle Bybit retries, uncertain order outcomes, stream recovery and shutdown."},"headers":[],"relativePath":"guides/production.md","filePath":"guides/production.md"}'),n={name:"guides/production.md"};function i(s,e,d,c,l,u){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="production-usage" tabindex="-1">Production usage <a class="header-anchor" href="#production-usage" aria-label="Permalink to &quot;Production usage&quot;">​</a></h1><p>Use the <a href="/docs/bybit/getting-started.html">Quickstart</a> to verify connectivity, then make request outcomes and connection state explicit in your application.</p><h2 id="set-timeouts-and-bound-concurrency" tabindex="-1">Set timeouts and bound concurrency <a class="header-anchor" href="#set-timeouts-and-bound-concurrency" aria-label="Permalink to &quot;Set timeouts and bound concurrency&quot;">​</a></h2><p>Choose an HTTP timeout appropriate to the operation and your application&#39;s latency budget. Set a maximum number of concurrent requests and avoid polling the same endpoint from many independent workers.</p><p><a href="/docs/bybit/guides/configuration.html">Configure request options</a>.</p><h2 id="retry-reads-deliberately" tabindex="-1">Retry reads deliberately <a class="header-anchor" href="#retry-reads-deliberately" aria-label="Permalink to &quot;Retry reads deliberately&quot;">​</a></h2><p>Retry transient read failures with bounded exponential backoff and jitter. Respect rate-limit responses and server retry guidance. Stop after a defined number of attempts or deadline. Parameter, permission and signature failures need correction before another attempt.</p><h2 id="resolve-uncertain-order-outcomes" tabindex="-1">Resolve uncertain order outcomes <a class="header-anchor" href="#resolve-uncertain-order-outcomes" aria-label="Permalink to &quot;Resolve uncertain order outcomes&quot;">​</a></h2><p>A timeout can occur after an exchange has accepted an order. For order submissions, track your <code>orderLinkId</code>. After an uncertain result, query <code>getActiveOrders()</code> with the appropriate category and order identifier, then consult order history or executions as needed. A missing result in one query is not proof that the original order never existed.</p><p>Persist the identifiers needed for reconciliation before submitting an order. Distinguish a transport acknowledgement, an accepted order and a fill in your application state.</p><h2 id="recover-streaming-state" tabindex="-1">Recover streaming state <a class="header-anchor" href="#recover-streaming-state" aria-label="Permalink to &quot;Recover streaming state&quot;">​</a></h2><p>Listen for <code>reconnect</code>, <code>reconnected</code> and <code>exception</code>. The client manages reconnection and remembered subscriptions, but your application must decide when its local state is current again. After a gap, reconcile orders and positions with REST before acting on cached state.</p><p>Bybit V5 channels have different snapshot and delta semantics. Follow the documentation for each topic instead of treating every update as a complete replacement.</p><p>Record the last update time and mark stale feeds explicitly. Avoid placing new orders based solely on a reconnected event.</p><h2 id="observe-failures-without-exposing-credentials" tabindex="-1">Observe failures without exposing credentials <a class="header-anchor" href="#observe-failures-without-exposing-credentials" aria-label="Permalink to &quot;Observe failures without exposing credentials&quot;">​</a></h2><p>Record operation names, response codes, request duration, retry counts and reconnect events. Log selected fields rather than complete request or error objects. See <a href="/docs/bybit/guides/errors.html">Error handling</a> for this SDK&#39;s response shapes.</p><h2 id="shut-down-cleanly" tabindex="-1">Shut down cleanly <a class="header-anchor" href="#shut-down-cleanly" aria-label="Permalink to &quot;Shut down cleanly&quot;">​</a></h2><p>Stop accepting new work, settle or reconcile outstanding requests, call <code>WebsocketClient.closeAll()</code>, and clear application timers. The <a href="/docs/bybit/guides/websockets.html">stream example</a> shows signal handlers and a bounded run.</p><h2 id="keep-the-sdk-up-to-date" tabindex="-1">Keep the SDK up to date <a class="header-anchor" href="#keep-the-sdk-up-to-date" aria-label="Permalink to &quot;Keep the SDK up to date&quot;">​</a></h2><p>Use the latest SDK release. Review release notes and run your application&#39;s integration checks before deploying an upgrade. Commit your lockfile for reproducible deployments.</p><p><a href="https://github.com/sieblyio/bybit-api/releases" target="_blank" rel="noreferrer">Repository releases</a> · <a href="https://bybit-exchange.github.io/docs/v5/intro" target="_blank" rel="noreferrer">Current exchange documentation</a></p>',21)])])}const m=t(n,[["render",i]]);export{h as __pageData,m as default};
